import { useEffect, useMemo, useState } from "react";
import {
  Activity, Bell, ChefHat, ChevronDown, CircleDollarSign, Clock3, Eye, LayoutDashboard,
  Menu as MenuIcon, Package, Plus, Search, Settings2, ShoppingBag, Store, Table2,
  Users, Utensils, WalletCards, Zap, CheckCircle2, ArrowUpLeft, MoreHorizontal,
  Truck, Megaphone, Boxes, ShieldCheck
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { useAuth } from "@/_core/hooks/useAuth";
import { startLogin } from "@/const";
import { toast } from "sonner";
import { trpc } from "@/lib/trpc";
import { shouldRedirectAfterLogout } from "@/lib/profileActions";
import Barcode from "react-barcode";

type OrderStatus = "new" | "preparing" | "ready" | "completed";
type NavKey = "overview" | "admin" | "branches" | "orders" | "pos" | "kds" | "menu" | "tables" | "inventory" | "team" | "marketing" | "remote" | "security";

type Order = { id: string; table: string; items: string; total: number; status: OrderStatus; time: string; channel: string };

const navItems: { key: NavKey; label: string; icon: typeof LayoutDashboard }[] = [
  { key: "overview", label: "نظرة عامة", icon: LayoutDashboard },
  { key: "admin", label: "Super Admin", icon: ShieldCheck },
  { key: "branches", label: "الفروع والإعدادات", icon: Store },
  { key: "orders", label: "الطلبات", icon: ShoppingBag },
  { key: "pos", label: "نقطة البيع POS", icon: WalletCards },
  { key: "kds", label: "شاشة المطبخ KDS", icon: ChefHat },
  { key: "menu", label: "المنيو والأصناف", icon: Utensils },
  { key: "tables", label: "الطاولات", icon: Table2 },
  { key: "inventory", label: "المخزون والمشتريات", icon: Boxes },
  { key: "team", label: "الموظفون والحضور", icon: Users },
  { key: "marketing", label: "التسويق والحملات", icon: Megaphone },
  { key: "remote", label: "التوظيف عن بُعد", icon: Users },
  { key: "security", label: "أمان الحساب والجلسات", icon: ShieldCheck },
];

const initialOrders: Order[] = [
  { id: "#1048", table: "طاولة 12", items: "برجر كلاسيك × 2، بطاطس × 1", total: 86, status: "new", time: "منذ 2 د", channel: "داخل المطعم" },
  { id: "#1047", table: "طاولة 04", items: "بيتزا خضار × 1، مياه × 2", total: 58, status: "preparing", time: "منذ 8 د", channel: "داخل المطعم" },
  { id: "#1046", table: "سفري", items: "تشيكن راب × 2، كولا × 2", total: 64, status: "ready", time: "منذ 12 د", channel: "استلام" },
  { id: "#1045", table: "طاولة 08", items: "سلطة سيزر × 1، باستا ألفريدو × 1", total: 74, status: "completed", time: "منذ 19 د", channel: "داخل المطعم" },
];

const statusLabels: Record<OrderStatus, string> = { new: "جديد", preparing: "قيد التحضير", ready: "جاهز", completed: "مكتمل" };
const statusStyles: Record<OrderStatus, string> = { new: "bg-amber-50 text-amber-700 border-amber-200", preparing: "bg-blue-50 text-blue-700 border-blue-200", ready: "bg-emerald-50 text-emerald-700 border-emerald-200", completed: "bg-slate-100 text-slate-600 border-slate-200" };

function money(value: number) { return `${value.toLocaleString("ar-SA")} ر.س`; }

export default function Home() {
  const { user, loading, logout } = useAuth();
  const [testEmail, setTestEmail] = useState("nfood@ret.com");
  const [testPassword, setTestPassword] = useState("");
  const testLogin = trpc.auth.testLogin.useMutation({ onSuccess: () => { toast.success("تم تسجيل الدخول لحساب الاختبار"); window.location.reload(); }, onError: (error) => toast.error(error.message || "بيانات الدخول غير صحيحة") });
  const [active, setActive] = useState<NavKey>("overview");
  const visibleNavItems = useMemo(() => { const role = user?.testRole; if (!role || role === "restaurant_admin") return navItems; const allowed: Record<string, NavKey[]> = { waiter: ["overview", "orders", "tables", "remote", "security"], kitchen: ["overview", "kds", "orders", "security"], cashier: ["overview", "pos", "orders", "tables", "security"], customer: ["overview", "orders", "security"], driver: ["overview", "orders", "remote", "security"] }; const keys = allowed[role] ?? ["overview"]; return navItems.filter((item) => keys.includes(item.key)); }, [user?.testRole]);
  const [selectedRestaurantId, setSelectedRestaurantId] = useState(1);
  const restaurantsQuery = trpc.platform.restaurants.useQuery(undefined, { enabled: Boolean(user), retry: false });
  const selectedRestaurantQuery = trpc.platform.restaurantById.useQuery({ id: selectedRestaurantId }, { enabled: Boolean(user), retry: false });
  const selectedRestaurant = selectedRestaurantQuery.data;
  const [profileOpen, setProfileOpen] = useState(false);
  const [notificationOpen, setNotificationOpen] = useState(false);
  const notificationsQuery = trpc.notifications.mine.useQuery(undefined, { enabled: Boolean(user), retry: false, refetchInterval: 5000 });
  const markNotificationRead = trpc.notifications.markRead.useMutation({ onSuccess: () => notificationsQuery.refetch() });
  const [orders, setOrders] = useState(initialOrders);
  const remoteOrders = trpc.platform.orders.useQuery({ branchId: 1 }, { enabled: Boolean(user), retry: false, refetchInterval: 5000 });
  const updateOrderStatus = trpc.platform.updateOrderStatus.useMutation({ onSuccess: () => { remoteOrders.refetch(); toast.success("تم حفظ حالة الطلب في قاعدة البيانات"); }, onError: (error) => toast.error(`تعذر تحديث الطلب: ${error.message}`) });
  const [branch, setBranch] = useState("فرع العليا");
  const [query, setQuery] = useState("");
  useEffect(() => {
    if (remoteOrders.data?.length) setOrders(remoteOrders.data.map((order) => ({ id: `#${order.id}`, table: order.tableName ?? "بدون طاولة", items: "بنود محفوظة في الطلب", total: Number(order.total), status: order.status === "cancelled" ? "completed" : order.status, time: new Date(order.createdAt).toLocaleTimeString("ar-SA", { hour: "2-digit", minute: "2-digit" }), channel: order.channel === "dine_in" ? "داخل المطعم" : order.channel === "takeaway" ? "استلام" : "توصيل" }))); }, [remoteOrders.data]);
  useEffect(() => {
    const channel = typeof BroadcastChannel !== "undefined" ? new BroadcastChannel("nfood-orders") : null;
    const receive = (event: MessageEvent | StorageEvent) => { const nextOrders = "data" in event ? event.data : event.newValue ? JSON.parse(event.newValue) : null; if (Array.isArray(nextOrders)) setOrders(nextOrders); };
    channel?.addEventListener("message", receive as EventListener);
    window.addEventListener("storage", receive);
    return () => { channel?.removeEventListener("message", receive as EventListener); channel?.close(); window.removeEventListener("storage", receive); };
  }, []);

  const visibleOrders = useMemo(() => orders.filter((order) => `${order.id} ${order.table} ${order.items}`.includes(query)), [orders, query]);
  const advanceOrder = (id: string) => {
    const current = orders.find((order) => order.id === id);
    if (!current) return;
    const next: OrderStatus = current.status === "new" ? "preparing" : current.status === "preparing" ? "ready" : "completed";
    const numericId = Number(id.replace("#", ""));
    if (remoteOrders.data?.some((order) => order.id === numericId)) { updateOrderStatus.mutate({ orderId: numericId, status: next }); return; }
    setOrders((items) => items.map((order) => order.id === id ? { ...order, status: next } : order));
    toast.info("تم تحديث المعاينة المحلية؛ سجّل الدخول لحفظ الطلب في قاعدة البيانات");
  };

  if (loading) return <div dir="rtl" className="flex min-h-screen items-center justify-center bg-[#f6f7f9] text-slate-500">جارٍ التحقق من الجلسة...</div>;
  if (!user) return <TestLoginScreen email={testEmail} password={testPassword} setEmail={setTestEmail} setPassword={setTestPassword} onSubmit={() => testLogin.mutate({ email: testEmail, password: testPassword })} pending={testLogin.isPending} onOAuth={() => startLogin()} />;

  const title = navItems.find((item) => item.key === active)?.label ?? "نظرة عامة";
  const handleLogout = async () => { try { await logout(); setProfileOpen(false); toast.success("تم تسجيل الخروج"); if (shouldRedirectAfterLogout(true)) window.location.href = "/"; } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر تسجيل الخروج"); } };
  const handleSwitchAccount = async () => { try { await logout(); setProfileOpen(false); startLogin(); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر تبديل الحساب"); } };
  return (
    <div dir="rtl" className="min-h-screen bg-[#f6f7f9] text-[#182230]">
      <aside className="fixed inset-y-0 right-0 z-20 hidden w-[272px] border-l border-slate-200 bg-[#111c2e] text-white lg:flex lg:flex-col">
        <div className="flex h-20 items-center gap-3 border-b border-white/10 px-7">
          <div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-[#e76f3c] shadow-lg shadow-orange-900/20"><Utensils className="h-5 w-5" /></div>
          <div><div className="text-[17px] font-bold tracking-tight">NFOOD</div><div className="text-[10px] font-medium text-slate-400">RESTAURANT OPERATING SYSTEM</div></div>
        </div>
        <div className="px-5 pt-7"><p className="mb-3 px-3 text-[10px] font-bold tracking-[.18em] text-slate-500">مساحة العمل</p>
          <nav className="space-y-1">{visibleNavItems.map((item) => { const Icon = item.icon; const isActive = item.key === active; return <button key={item.key} onClick={() => setActive(item.key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-right text-[13px] transition-all ${isActive ? "bg-[#e76f3c] font-semibold text-white shadow-lg shadow-orange-950/20" : "text-slate-400 hover:bg-white/5 hover:text-white"}`}><Icon className="h-[18px] w-[18px]" /><span>{item.label}</span>{item.key === "orders" && <span className="mr-auto rounded-full bg-white/15 px-2 py-0.5 text-[10px] text-white">4</span>}</button>; })}</nav>
        </div>
        <div className="mt-auto space-y-4 p-5"><div className="rounded-2xl border border-white/10 bg-white/[.04] p-4"><div className="mb-2 flex items-center gap-2 text-xs font-semibold"><Zap className="h-4 w-4 text-[#f0ad65]" /> الباقة الحالية</div><p className="text-sm font-bold">Growth Plan</p><p className="mt-1 text-[11px] text-slate-400">24 يوماً متبقية في التجربة</p><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-white/10"><div className="h-full w-[68%] rounded-full bg-[#f0ad65]" /></div></div><button className="flex w-full items-center gap-3 px-3 py-2 text-sm text-slate-400 hover:text-white"><Settings2 className="h-4 w-4" /> الإعدادات العامة</button></div>
      </aside>
      <main className="lg:mr-[272px]">
        <header className="sticky top-0 z-10 flex h-20 items-center justify-between border-b border-slate-200/80 bg-[#f6f7f9]/90 px-5 backdrop-blur-xl md:px-8"><div><div className="mb-1 flex items-center gap-2 text-xs text-slate-500"><span>مساحة العمل</span><span>/</span><span className="font-medium text-slate-700">{selectedRestaurant?.name || "مطعم NFOOD"}</span></div><h1 className="text-xl font-bold tracking-tight md:text-2xl">{title}</h1></div><div className="flex items-center gap-3"><div className="hidden items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs font-semibold shadow-sm sm:flex"><Store className="h-4 w-4 text-[#e76f3c]" /><select aria-label="اختيار المطعم" value={selectedRestaurantId} onChange={(e) => setSelectedRestaurantId(Number(e.target.value))} className="max-w-36 bg-transparent outline-none"><option value={1}>مطعم NFOOD</option>{(restaurantsQuery.data ?? []).filter((restaurant) => restaurant.id !== 1).map((restaurant) => <option key={restaurant.id} value={restaurant.id}>{restaurant.name}</option>)}</select><span className="text-slate-300">/</span><select aria-label="اختيار الفرع" value={branch} onChange={(e) => setBranch(e.target.value)} className="bg-transparent outline-none"><option>فرع العليا</option><option>فرع الملز</option><option>فرع النخيل</option></select></div><div className="relative"><button aria-label="فتح الإشعارات" aria-expanded={notificationOpen} onClick={() => setNotificationOpen((open) => !open)} className="relative rounded-xl border border-slate-200 bg-white p-2.5 text-slate-500 shadow-sm hover:text-[#e76f3c]"><Bell className="h-[18px] w-[18px]" />{(notificationsQuery.data ?? []).some((item) => !item.readAt) && <span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-[#e76f3c]" />}</button>{notificationOpen && <div className="absolute left-0 top-12 z-50 w-80 rounded-2xl border border-slate-200 bg-white p-2 shadow-xl"><div className="flex items-center justify-between border-b border-slate-100 px-3 py-2"><p className="text-sm font-bold">الإشعارات</p><span className="text-[10px] text-slate-400">{notificationsQuery.data?.length ?? 0}</span></div><div className="max-h-72 overflow-y-auto">{(notificationsQuery.data ?? []).length === 0 ? <p className="px-3 py-8 text-center text-xs text-slate-500">لا توجد إشعارات.</p> : (notificationsQuery.data ?? []).map((item) => <button key={item.id} onClick={() => markNotificationRead.mutate({ notificationId: item.id })} className={`w-full rounded-xl px-3 py-3 text-right hover:bg-orange-50 ${item.readAt ? "opacity-60" : ""}`}><p className="text-xs font-bold">{item.title}</p><p className="mt-1 text-xs text-slate-500">{item.body}</p></button>)}</div></div>}</div><div className="relative hidden sm:block"><button aria-label="فتح قائمة الملف الشخصي" aria-expanded={profileOpen} onClick={() => setProfileOpen((open) => !open)} className="flex h-9 w-9 items-center justify-center rounded-xl bg-[#e76f3c] text-sm font-bold text-white shadow-sm transition hover:bg-[#d85f2e]">{user?.name?.[0] || "م"}</button>{profileOpen && <div className="absolute left-0 top-11 z-50 w-64 rounded-2xl border border-slate-200 bg-white p-2 text-right shadow-xl"><div className="border-b border-slate-100 px-3 py-3"><p className="text-sm font-bold">{user?.name || "حساب NFOOD"}</p><p className="mt-1 truncate text-xs text-slate-500">{user?.email || "لم يتم تسجيل الدخول"}</p></div><button onClick={handleSwitchAccount} className="mt-2 flex w-full items-center rounded-xl px-3 py-2.5 text-sm text-slate-700 hover:bg-orange-50 hover:text-[#e76f3c]">تبديل الحساب</button><button onClick={handleLogout} className="flex w-full items-center rounded-xl px-3 py-2.5 text-sm text-red-600 hover:bg-red-50">تسجيل الخروج</button></div>}</div></div></header>
        <div className="border-b border-slate-200 bg-white px-4 py-2 lg:hidden"><div className="flex gap-2 overflow-x-auto pb-1">{navItems.map((item) => { const Icon = item.icon; return <button key={item.key} onClick={() => setActive(item.key)} className={`flex shrink-0 items-center gap-1.5 rounded-lg px-3 py-2 text-[11px] font-semibold ${active === item.key ? "bg-orange-50 text-[#e76f3c]" : "text-slate-500"}`}><Icon className="h-3.5 w-3.5" />{item.label}</button>; })}</div></div><div className="p-5 md:p-8"><div className="mb-7 flex items-end justify-between"><div><p className="text-sm text-slate-500">الأربعاء، 20 أغسطس 2026</p><h2 className="mt-1 text-2xl font-bold">صباح الخير، فريق NFOOD</h2></div><Button onClick={() => { setActive("pos"); toast.success("تم فتح نقطة البيع"); }} className="hidden gap-2 rounded-xl bg-[#e76f3c] px-4 shadow-lg shadow-orange-200 hover:bg-[#d85f2e] sm:flex"><Plus className="h-4 w-4" /> طلب جديد</Button></div>
          {active === "overview" ? <Overview orders={visibleOrders} advanceOrder={advanceOrder} query={query} setQuery={setQuery} /> : <ModuleView active={active} orders={visibleOrders} advanceOrder={advanceOrder} setActive={setActive} restaurantId={selectedRestaurantId} />}
        </div>
      </main>
    </div>
  );
}

function Overview({ orders, advanceOrder, query, setQuery }: { orders: Order[]; advanceOrder: (id: string) => void; query: string; setQuery: (value: string) => void }) {
  const stats = [{ label: "مبيعات اليوم", value: "12,840 ر.س", change: "+18.4%", icon: CircleDollarSign, tint: "orange" }, { label: "الطلبات اليوم", value: "186", change: "+12.2%", icon: ShoppingBag, tint: "blue" }, { label: "متوسط قيمة الطلب", value: "69.03 ر.س", change: "+5.6%", icon: WalletCards, tint: "violet" }, { label: "الطاولات المشغولة", value: "18 / 32", change: "56% إشغال", icon: Table2, tint: "emerald" }];
  return <><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{stats.map((stat) => { const Icon = stat.icon; return <Card key={stat.label} className="rounded-2xl border-slate-200/80 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-start justify-between"><div className={`flex h-10 w-10 items-center justify-center rounded-xl ${stat.tint === "orange" ? "bg-orange-50 text-orange-600" : stat.tint === "blue" ? "bg-blue-50 text-blue-600" : stat.tint === "violet" ? "bg-violet-50 text-violet-600" : "bg-emerald-50 text-emerald-600"}`}><Icon className="h-5 w-5" /></div><span className="flex items-center gap-1 text-[11px] font-bold text-emerald-600"><ArrowUpLeft className="h-3 w-3" />{stat.change}</span></div><p className="mt-5 text-xs font-medium text-slate-500">{stat.label}</p><p className="mt-1 text-2xl font-bold tracking-tight">{stat.value}</p></CardContent></Card>; })}</div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.4fr_1fr]"><Card className="rounded-2xl border-slate-200/80 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">أداء المبيعات</CardTitle><p className="mt-1 text-xs text-slate-500">نظرة على مبيعات آخر 7 أيام</p></div><Badge variant="outline" className="rounded-lg border-slate-200 bg-slate-50 px-3 py-1.5 text-xs">هذا الأسبوع <ChevronDown className="mr-1 inline h-3 w-3" /></Badge></CardHeader><CardContent className="p-5"><div className="flex h-[180px] items-end gap-3 pt-5">{[42, 58, 48, 72, 63, 84, 96].map((height, index) => <div key={index} className="flex flex-1 flex-col items-center gap-3"><div className={`w-full rounded-t-lg transition-all hover:opacity-80 ${index === 6 ? "bg-[#e76f3c]" : "bg-orange-100"}`} style={{ height: `${height}%` }} /><span className="text-[10px] text-slate-400">{["الخميس", "الجمعة", "السبت", "الأحد", "الإثنين", "الثلاثاء", "اليوم"][index]}</span></div>)}</div><div className="mt-3 flex items-center gap-2 border-t border-slate-100 pt-4 text-xs text-slate-500"><span className="h-2 w-2 rounded-full bg-[#e76f3c]" /> إجمالي المبيعات <strong className="mr-auto text-sm text-slate-800">78,420 ر.س</strong></div></CardContent></Card>
      <Card className="rounded-2xl border-slate-200/80 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">الأصناف الأكثر مبيعاً</CardTitle><p className="mt-1 text-xs text-slate-500">حسب عدد الطلبات</p></div><Button variant="ghost" size="sm" className="text-xs text-[#e76f3c]" onClick={() => toast.info("سيتم فتح تقرير المنيو قريباً")}>عرض الكل</Button></CardHeader><CardContent className="space-y-4 p-5">{[["برجر كلاسيك", "86 طلب", "bg-orange-500", "82%"], ["بيتزا خضار", "64 طلب", "bg-amber-400", "64%"], ["تشيكن راب", "52 طلب", "bg-blue-400", "52%"], ["باستا ألفريدو", "41 طلب", "bg-violet-400", "41%"]].map(([name, count, color, width], index) => <div key={name} className="flex items-center gap-3"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-100 text-xs font-bold text-slate-500">0{index + 1}</span><div className="min-w-0 flex-1"><div className="mb-1 flex justify-between text-xs"><span className="font-semibold">{name}</span><span className="text-slate-400">{count}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-slate-100"><div className={`h-full rounded-full ${color}`} style={{ width }} /></div></div></div>)}</CardContent></Card></div>
    <Card className="mt-6 rounded-2xl border-slate-200/80 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">آخر الطلبات</CardTitle><p className="mt-1 text-xs text-slate-500">تحديث مباشر من نقطة البيع والمطبخ</p></div><div className="flex items-center gap-2"><div className="relative hidden sm:block"><Search className="absolute right-3 top-2.5 h-4 w-4 text-slate-400" /><Input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="بحث في الطلبات" className="h-9 w-44 rounded-lg border-slate-200 pr-9 text-xs" /></div><Button variant="outline" size="sm" className="rounded-lg text-xs">عرض الكل <ArrowUpLeft className="mr-1 h-3 w-3" /></Button></div></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-right text-sm"><thead className="bg-slate-50/70 text-[11px] text-slate-500"><tr><th className="px-5 py-3 font-medium">رقم الطلب</th><th className="px-5 py-3 font-medium">الطاولة / القناة</th><th className="px-5 py-3 font-medium">الأصناف</th><th className="px-5 py-3 font-medium">الإجمالي</th><th className="px-5 py-3 font-medium">الحالة</th><th className="px-5 py-3 font-medium">إجراء</th></tr></thead><tbody>{orders.length === 0 ? <tr><td colSpan={6} className="px-5 py-12 text-center"><div className="flex flex-col items-center text-slate-400"><ShoppingBag className="mb-3 h-8 w-8" /><p className="text-sm font-semibold">لا توجد طلبات حتى الآن</p><p className="mt-1 text-xs">ستظهر الطلبات الجديدة هنا عند استقبالها من نقطة البيع.</p></div></td></tr> : orders.map((order) => <tr key={order.id} className="border-t border-slate-100 transition-colors hover:bg-slate-50/60"><td className="px-5 py-4 font-bold">{order.id}<div className="mt-0.5 text-[10px] font-normal text-slate-400">{order.time}</div></td><td className="px-5 py-4"><div className="font-medium">{order.table}</div><div className="mt-0.5 text-[11px] text-slate-400">{order.channel}</div></td><td className="max-w-[240px] truncate px-5 py-4 text-xs text-slate-500">{order.items}</td><td className="px-5 py-4 font-bold">{money(order.total)}</td><td className="px-5 py-4"><Badge variant="outline" className={`rounded-lg px-2.5 py-1 text-[11px] ${statusStyles[order.status]}`}>{statusLabels[order.status]}</Badge></td><td className="px-5 py-4"><button onClick={() => order.status !== "completed" ? advanceOrder(order.id) : toast.info("الطلب مكتمل بالفعل")} className="rounded-lg p-2 text-slate-400 hover:bg-orange-50 hover:text-[#e76f3c]" title="تحديث الحالة">{order.status !== "completed" ? <CheckCircle2 className="h-4 w-4" /> : <Eye className="h-4 w-4" />}</button></td></tr>)}</tbody></table></div></CardContent></Card></>;
}

function ModuleView({ active, orders, advanceOrder, setActive, restaurantId }: { active: NavKey; orders: Order[]; advanceOrder: (id: string) => void; setActive: (key: NavKey) => void; restaurantId: number }) {
  const labels: Record<NavKey, { title: string; description: string; icon: typeof LayoutDashboard }> = { overview: { title: "نظرة عامة", description: "", icon: LayoutDashboard }, admin: { title: "Super Admin", description: "إدارة المطاعم والعملاء والاشتراكات والصلاحيات.", icon: ShieldCheck }, branches: { title: "الفروع والإعدادات", description: "إدارة الفروع وساعات العمل وإعداداتها التشغيلية.", icon: Store }, orders: { title: "إدارة الطلبات", description: "تابع الطلبات وحدّث مراحلها من شاشة واحدة.", icon: ShoppingBag }, pos: { title: "نقطة البيع POS", description: "أنشئ طلباً جديداً بسرعة واربطه بالفرع والطاولة.", icon: WalletCards }, kds: { title: "شاشة المطبخ KDS", description: "تنظيم الطلبات الواردة ومتابعة زمن التحضير لحظياً.", icon: ChefHat }, menu: { title: "المنيو والأصناف", description: "إدارة التصنيفات والأصناف والأسعار والتوفر.", icon: Utensils }, tables: { title: "الطاولات", description: "عرض إشغال الطاولات وربطها بالطلبات الحالية.", icon: Table2 }, inventory: { title: "المخزون والمشتريات", description: "متابعة المواد الخام والتنبيهات وتسجيل المشتريات.", icon: Package }, team: { title: "الموظفون والحضور", description: "إدارة الفريق والأدوار وسجل الحضور.", icon: Users }, marketing: { title: "التسويق والحملات", description: "العروض والكوبونات والحملات في مكان واحد.", icon: Megaphone }, remote: { title: "التوظيف عن بُعد", description: "أنشئ مهامًا مدفوعة وتواصل مع الموظفين من مكان واحد.", icon: Users }, security: { title: "أمان الحساب والجلسات", description: "أدر الأجهزة والجلسات والتحقق بخطوتين.", icon: ShieldCheck } };
  const info = labels[active]; const Icon = info.icon;
  if (active === "orders" || active === "kds") return <div><div className="mb-6 flex items-center gap-3"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-orange-50 text-[#e76f3c]"><Icon className="h-6 w-6" /></div><div><h2 className="text-xl font-bold">{info.title}</h2><p className="text-sm text-slate-500">{info.description}</p></div></div><div className="grid gap-4 md:grid-cols-4">{(["new", "preparing", "ready", "completed"] as OrderStatus[]).map((status) => <Card key={status} className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="px-4 pb-2 pt-4"><CardTitle className="flex items-center justify-between text-sm">{statusLabels[status]}<span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs">{orders.filter((o) => o.status === status).length}</span></CardTitle></CardHeader><CardContent className="space-y-3 p-4 pt-2">{orders.filter((o) => o.status === status).map((order) => <div key={order.id} className="rounded-xl border border-slate-100 bg-slate-50/70 p-3"><div className="flex justify-between text-xs font-bold"><span>{order.id}</span><span className="text-slate-400">{order.time}</span></div><p className="mt-2 text-xs font-medium">{order.table}</p><p className="mt-1 text-[11px] leading-5 text-slate-500">{order.items}</p>{status !== "completed" && <Button onClick={() => advanceOrder(order.id)} size="sm" className="mt-3 h-8 w-full rounded-lg bg-[#e76f3c] text-xs hover:bg-[#d85f2e]">نقل إلى {statusLabels[status === "new" ? "preparing" : status === "preparing" ? "ready" : "completed"]}</Button>}</div>)}</CardContent></Card>)}</div></div>;
  if (active === "pos") return <PosView restaurantId={restaurantId} />;
  if (active === "menu") return <MenuView restaurantId={restaurantId} />;
  if (active === "tables") return <TablesView restaurantId={restaurantId} />;
  if (active === "inventory") return <InventoryView restaurantId={restaurantId} />;
  if (active === "team") return <TeamView restaurantId={restaurantId} />;
  if (active === "marketing") return <MarketingView restaurantId={restaurantId} />;
  if (active === "admin") return <SuperAdminView />;
  if (active === "branches") return <BranchesView restaurantId={restaurantId} />;
  if (active === "remote") return <RemoteWorkView restaurantId={restaurantId} />;
  if (active === "security") return <SecurityView />;
  return <div><div className="mb-6 flex items-center gap-3"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-orange-50 text-[#e76f3c]"><Icon className="h-6 w-6" /></div><div><h2 className="text-xl font-bold">{info.title}</h2><p className="text-sm text-slate-500">{info.description}</p></div></div><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="flex min-h-[380px] flex-col items-center justify-center p-8 text-center"><div className="mb-4 flex h-16 w-16 items-center justify-center rounded-3xl bg-orange-50 text-[#e76f3c]"><Icon className="h-8 w-8" /></div><h3 className="text-lg font-bold">وحدة {info.title}</h3><p className="mt-2 max-w-md text-sm leading-7 text-slate-500">تم تجهيز مساحة العمل لهذه الوحدة ضمن النظام الموحد. ستظهر هنا أدوات الإدارة والتقارير والعمليات المرتبطة بالفرع المختار.</p><Button onClick={() => { setActive("overview"); toast.success("تم الرجوع إلى لوحة النظرة العامة"); }} className="mt-6 rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">العودة للوحة الرئيسية</Button></CardContent></Card></div>;
}


type MenuProduct = { id: number; name: string; category: string; price: number; available: boolean };
const menuProducts: MenuProduct[] = [
  { id: 1, name: "برجر كلاسيك", category: "البرجر", price: 42, available: true },
  { id: 2, name: "بيتزا خضار", category: "البيتزا", price: 48, available: true },
  { id: 3, name: "تشيكن راب", category: "السندويتشات", price: 32, available: true },
  { id: 4, name: "باستا ألفريدو", category: "الباستا", price: 44, available: false },
  { id: 5, name: "سلطة سيزر", category: "المقبلات", price: 30, available: true },
  { id: 6, name: "بطاطس مقلية", category: "الإضافات", price: 14, available: true },
];

function MenuView({ restaurantId }: { restaurantId: number }) {
  const { user } = useAuth();
  const remoteMenu = trpc.platform.menuItems.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false });
  const [products, setProducts] = useState(menuProducts);
  const [category, setCategory] = useState("الكل");
  useEffect(() => { if (remoteMenu.data?.length) setProducts(remoteMenu.data.map((item) => ({ id: item.id, name: item.name, category: String(item.categoryId), price: Number(item.price), available: item.isAvailable }))); }, [remoteMenu.data]);
  const categories = ["الكل", ...Array.from(new Set(products.map((product) => product.category)))];
  const shown = products.filter((product) => category === "الكل" || product.category === category);
  return <div><div className="mb-6 flex items-center justify-between"><div><h2 className="text-xl font-bold">المنيو والأصناف</h2><p className="mt-1 text-sm text-slate-500">تحكم سريع في الأصناف والأسعار والتوفر.</p></div><Button onClick={() => toast.success("تم فتح نموذج إضافة صنف جديد")} className="gap-2 rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]"><Plus className="h-4 w-4" /> إضافة صنف</Button></div><div className="mb-5 flex gap-2 overflow-x-auto">{categories.map((item) => <button key={item} onClick={() => setCategory(item)} className={`shrink-0 rounded-xl px-4 py-2 text-xs font-semibold ${category === item ? "bg-[#111c2e] text-white" : "bg-white text-slate-500 shadow-sm"}`}>{item}</button>)}</div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{shown.map((product) => <Card key={product.name} className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="mb-4 flex items-start justify-between"><div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-orange-50 text-xl">🍽</div><button onClick={() => setProducts((items) => items.map((item) => item.name === product.name ? { ...item, available: !item.available } : item))} className={`rounded-lg px-2.5 py-1 text-[10px] font-bold ${product.available ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500"}`}>{product.available ? "متوفر" : "غير متوفر"}</button></div><h3 className="font-bold">{product.name}</h3><p className="mt-1 text-xs text-slate-400">{product.category}</p><div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-3"><span className="text-lg font-bold">{money(product.price)}</span><button onClick={() => toast.info(`تعديل ${product.name}`)} className="rounded-lg p-2 text-slate-400 hover:bg-orange-50 hover:text-[#e76f3c]"><MoreHorizontal className="h-4 w-4" /></button></div></CardContent></Card>)}</div></div>;
}

function PosView({ restaurantId }: { restaurantId: number }) {
  const { user } = useAuth();
  const remoteMenu = trpc.platform.menuItems.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false });
  const posProducts: MenuProduct[] = remoteMenu.data?.length ? remoteMenu.data.map((item) => ({ id: item.id, name: item.name, category: String(item.categoryId), price: Number(item.price), available: item.isAvailable })) : menuProducts;
  const [cart, setCart] = useState<{ product: MenuProduct; quantity: number }[]>([]);
  const createOrder = trpc.platform.createOrder.useMutation({ onSuccess: (result) => { toast.success(`تم حفظ الطلب #${result.orderId} وإرساله للمطبخ`); setCart([]); }, onError: (error) => toast.error(`تعذر حفظ الطلب: ${error.message}`) });
  const [channel, setChannel] = useState("داخل المطعم");
  const total = cart.reduce((sum, item) => sum + item.product.price * item.quantity, 0);
  const add = (product: MenuProduct) => setCart((items) => { const found = items.find((item) => item.product.name === product.name); return found ? items.map((item) => item.product.name === product.name ? { ...item, quantity: item.quantity + 1 } : item) : [...items, { product, quantity: 1 }]; });
  return <div><div className="mb-6 flex items-center justify-between"><div><h2 className="text-xl font-bold">نقطة البيع POS</h2><p className="mt-1 text-sm text-slate-500">أنشئ طلباً جديداً واختر القناة والطاولة ثم أتمم الدفع.</p></div><Badge className="rounded-lg bg-emerald-50 text-emerald-700 hover:bg-emerald-50"><Activity className="ml-1 h-3.5 w-3.5" /> متصل</Badge></div><div className="grid gap-5 xl:grid-cols-[1fr_360px]"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><div className="flex items-center justify-between"><CardTitle className="text-base">الأصناف المتاحة</CardTitle><div className="flex gap-2">{["داخل المطعم", "استلام", "توصيل"].map((item) => <button key={item} onClick={() => setChannel(item)} className={`rounded-lg px-3 py-1.5 text-[11px] font-semibold ${channel === item ? "bg-orange-50 text-[#e76f3c]" : "text-slate-400"}`}>{item}</button>)}</div></div></CardHeader><CardContent className="grid gap-3 p-5 sm:grid-cols-2 lg:grid-cols-3">{posProducts.filter((product) => product.available).map((product) => <button key={product.name} onClick={() => add(product)} className="rounded-2xl border border-slate-100 bg-slate-50/60 p-4 text-right transition hover:border-orange-200 hover:bg-orange-50/40"><div className="flex items-center justify-between"><span className="text-xl">🍽</span><Plus className="h-4 w-4 text-[#e76f3c]" /></div><p className="mt-4 text-sm font-bold">{product.name}</p><p className="mt-1 text-xs text-slate-500">{money(product.price)}</p></button>)}</CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><CardTitle className="flex items-center justify-between text-base">الطلب الحالي<span className="text-xs font-normal text-slate-400">{channel}</span></CardTitle></CardHeader><CardContent className="p-5"><div className="min-h-[220px] space-y-3">{cart.length === 0 ? <div className="flex h-[220px] flex-col items-center justify-center text-center text-slate-400"><ShoppingBag className="mb-3 h-8 w-8" /><p className="text-sm">السلة فارغة</p><p className="mt-1 text-xs">اختر صنفاً لإضافته للطلب</p></div> : cart.map((item) => <div key={item.product.name} className="flex items-center justify-between rounded-xl bg-slate-50 p-3"><div><p className="text-xs font-bold">{item.product.name}</p><p className="mt-1 text-[11px] text-slate-400">{item.quantity} × {money(item.product.price)}</p></div><div className="flex items-center gap-2"><button onClick={() => setCart((items) => items.flatMap((current) => current.product.name === item.product.name ? current.quantity > 1 ? [{ ...current, quantity: current.quantity - 1 }] : [] : [current]))} className="rounded-md bg-white px-2 py-1 text-xs">−</button><span className="text-xs font-bold">{item.quantity}</span><button onClick={() => add(item.product)} className="rounded-md bg-white px-2 py-1 text-xs">+</button></div></div>)}</div><div className="border-t border-slate-100 pt-4"><div className="mb-3 flex justify-between text-sm"><span className="text-slate-500">الإجمالي</span><strong className="text-lg">{money(total)}</strong></div><Button disabled={!cart.length || createOrder.isPending} onClick={() => createOrder.mutate({ restaurantId, branchId: 1, channel: channel === "داخل المطعم" ? "dine_in" : channel === "استلام" ? "takeaway" : "delivery", total: total.toFixed(2), items: cart.map((item) => ({ menuItemId: item.product.id, quantity: item.quantity, unitPrice: item.product.price.toFixed(2) })) })} className="w-full rounded-xl bg-[#e76f3c] py-5 hover:bg-[#d85f2e]">{createOrder.isPending ? "جارٍ حفظ الطلب..." : "إتمام الدفع وإرسال للمطبخ"}</Button></div></CardContent></Card></div></div>;
}


function SecurityView() {
  const sessionsQuery = trpc.security.sessions.useQuery(undefined, { retry: false });
  const securityQuery = trpc.security.security.useQuery(undefined, { retry: false });
  const utils = trpc.useUtils();
  const revokeAll = trpc.security.revokeAllSessions.useMutation({ onSuccess: () => { toast.success("تم تسجيل الخروج من جميع الأجهزة"); sessionsQuery.refetch(); } });
  const setTwoFactor = trpc.security.setTwoFactor.useMutation({ onSuccess: (result) => { toast.success(result.enabled ? "تم تفعيل 2FA" : "تم تعطيل 2FA"); utils.security.security.invalidate(); } });
  const twoFactorEnabled = securityQuery.data?.twoFactorEnabled ?? false;
  return <div><div className="mb-6"><h2 className="text-xl font-bold">أمان الحساب والجلسات</h2><p className="mt-1 text-sm text-slate-500">إدارة الأجهزة المسجلة وخيارات الحماية من داخل الحساب.</p></div><div className="grid gap-5 lg:grid-cols-[1fr_360px]"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex flex-row items-center justify-between border-b border-slate-100"><CardTitle className="text-base">الأجهزة والجلسات</CardTitle><Button variant="outline" onClick={() => revokeAll.mutate()} disabled={revokeAll.isPending} className="rounded-xl text-xs text-red-600">تسجيل الخروج من الجميع</Button></CardHeader><CardContent className="space-y-3 p-5">{sessionsQuery.isLoading ? <div className="h-16 animate-pulse rounded-xl bg-slate-100" /> : (sessionsQuery.data ?? []).length === 0 ? <p className="rounded-xl bg-slate-50 p-6 text-center text-sm text-slate-500">لا توجد جلسات محفوظة.</p> : (sessionsQuery.data ?? []).map((session) => <div key={session.id} className="flex items-center justify-between rounded-xl border border-slate-100 p-4"><div><p className="text-sm font-semibold">{session.deviceLabel || "جهاز غير معروف"}</p><p className="mt-1 text-xs text-slate-500">{session.ipAddress || "IP غير متاح"} · آخر نشاط {new Date(session.lastSeenAt).toLocaleString("ar-SA")}</p></div><Badge className={session.revokedAt ? "bg-slate-100 text-slate-500" : "bg-emerald-50 text-emerald-700"}>{session.revokedAt ? "منتهية" : "نشطة"}</Badge></div>)}</CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader><CardTitle className="text-base">التحقق بخطوتين</CardTitle></CardHeader><CardContent><p className="mb-5 text-sm leading-6 text-slate-500">أضف طبقة حماية إضافية للحساب. تفعيل 2FA هنا محفوظ فعليًا ويمكن ربطه بمزود OTP في المرحلة التالية.</p><Button onClick={() => setTwoFactor.mutate({ enabled: !twoFactorEnabled })} disabled={setTwoFactor.isPending} className={`w-full rounded-xl ${twoFactorEnabled ? "bg-emerald-600 hover:bg-emerald-700" : "bg-[#e76f3c] hover:bg-[#d85f2e]"}`}>{twoFactorEnabled ? "2FA مفعّل — تعطيل" : "تفعيل 2FA"}</Button></CardContent></Card></div></div>;
}

function SectionHeading({ title, description, action }: { title: string; description: string; action: string }) { return <div className="mb-6 flex items-center justify-between"><div><h2 className="text-xl font-bold">{title}</h2><p className="mt-1 text-sm text-slate-500">{description}</p></div><Button onClick={() => toast.success(`تم فتح ${action}`)} className="gap-2 rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]"><Plus className="h-4 w-4" /> {action}</Button></div>; }

function TablesView({ restaurantId }: { restaurantId: number }) { const [tables, setTables] = useState([true, false, true, false, false, true, true, false, false, true, false, false]); return <div><SectionHeading title="إدارة الطاولات" description="تخطيط بصري لحالة الطاولات والطلبات المرتبطة." action="إضافة طاولة" /><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="grid grid-cols-2 gap-4 p-6 sm:grid-cols-3 md:grid-cols-4 xl:grid-cols-6">{tables.map((occupied, index) => <button key={index} onClick={() => setTables((items) => items.map((item, itemIndex) => itemIndex === index ? !item : item))} className={`relative flex aspect-square flex-col items-center justify-center rounded-3xl border-2 transition-all ${occupied ? "border-orange-200 bg-orange-50 text-orange-700" : "border-emerald-200 bg-emerald-50 text-emerald-700"}`}><Table2 className="mb-2 h-7 w-7" /><span className="text-sm font-bold">طاولة {String(index + 1).padStart(2, "0")}</span><span className="mt-1 text-[10px]">{occupied ? "مشغولة" : "متاحة"}</span>{occupied && <span className="absolute right-3 top-3 h-2 w-2 rounded-full bg-orange-500" />}</button>)}</CardContent></Card></div>; }

function InventoryView({ restaurantId }: { restaurantId: number }) { const [items, setItems] = useState([{ name: "لحم برجر", quantity: 18, unit: "كجم", minimum: 12 }, { name: "جبنة شيدر", quantity: 7, unit: "كجم", minimum: 10 }, { name: "خبز بريوش", quantity: 42, unit: "قطعة", minimum: 24 }, { name: "خضار مشكلة", quantity: 5, unit: "كجم", minimum: 8 }]); return <div><SectionHeading title="المخزون والمشتريات" description="راقب المواد الخام والتنبيهات وسجّل المشتريات." action="تسجيل شراء" /><div className="mb-5 grid gap-4 sm:grid-cols-3"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><p className="text-xs text-slate-500">قيمة المخزون التقديرية</p><p className="mt-2 text-2xl font-bold">18,240 ر.س</p></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><p className="text-xs text-slate-500">أصناف منخفضة</p><p className="mt-2 text-2xl font-bold text-amber-600">{items.filter((item) => item.quantity < item.minimum).length}</p></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><p className="text-xs text-slate-500">آخر عملية شراء</p><p className="mt-2 text-lg font-bold">اليوم، 09:40</p></CardContent></Card></div><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-0"><table className="w-full text-right text-sm"><thead className="bg-slate-50 text-xs text-slate-500"><tr><th className="px-5 py-3">المادة</th><th className="px-5 py-3">الكمية الحالية</th><th className="px-5 py-3">الحد الأدنى</th><th className="px-5 py-3">الحالة</th><th className="px-5 py-3">إجراء</th></tr></thead><tbody>{items.map((item) => { const low = item.quantity < item.minimum; return <tr key={item.name} className="border-t border-slate-100"><td className="px-5 py-4 font-semibold">{item.name}</td><td className="px-5 py-4">{item.quantity} {item.unit}</td><td className="px-5 py-4 text-slate-500">{item.minimum} {item.unit}</td><td className="px-5 py-4"><Badge variant="outline" className={`rounded-lg text-[11px] ${low ? "border-amber-200 bg-amber-50 text-amber-700" : "border-emerald-200 bg-emerald-50 text-emerald-700"}`}>{low ? "يحتاج إعادة طلب" : "مستقر"}</Badge></td><td className="px-5 py-4"><button onClick={() => setItems((current) => current.map((currentItem) => currentItem.name === item.name ? { ...currentItem, quantity: currentItem.quantity + 10 } : currentItem))} className="text-xs font-semibold text-[#e76f3c]">+ إضافة كمية</button></td></tr>; })}</tbody></table></CardContent></Card></div>; }

function TeamView({ restaurantId }: { restaurantId: number }) { const [staff, setStaff] = useState([{ name: "سارة العتيبي", role: "مديرة الفرع", present: true }, { name: "أحمد القحطاني", role: "كاشير", present: true }, { name: "نورة الشهري", role: "قائدة المطبخ", present: false }, { name: "خالد المطيري", role: "ويتر", present: true }]); return <div><SectionHeading title="الموظفون والحضور" description="تابع الفريق والأدوار وحالة الحضور اليومية." action="إضافة موظف" /><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="grid gap-3 p-5 md:grid-cols-2">{staff.map((member) => <div key={member.name} className="flex items-center gap-3 rounded-2xl border border-slate-100 p-4"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#111c2e] text-sm font-bold text-white">{member.name[0]}</div><div className="min-w-0 flex-1"><p className="text-sm font-bold">{member.name}</p><p className="mt-1 text-xs text-slate-500">{member.role}</p></div><button onClick={() => setStaff((current) => current.map((item) => item.name === member.name ? { ...item, present: !item.present } : item))} className={`rounded-lg px-3 py-1.5 text-[11px] font-bold ${member.present ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500"}`}>{member.present ? "حاضر" : "غائب"}</button></div>)}</CardContent></Card></div>; }

function MarketingView({ restaurantId }: { restaurantId: number }) { const campaigns = [{ name: "عرض نهاية الأسبوع", code: "WEEKEND20", result: "124 استخدام", status: "نشطة" }, { name: "وجبة العائلة", code: "FAMILY15", result: "86 استخدام", status: "نشطة" }, { name: "عودة العملاء", code: "WELCOME10", result: "مجدولة", status: "مجدولة" }]; return <div><SectionHeading title="التسويق والحملات" description="أنشئ العروض والكوبونات وتابع أداء الحملات." action="حملة جديدة" /><div className="grid gap-4 md:grid-cols-3">{campaigns.map((campaign) => <Card key={campaign.code} className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-start justify-between"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-violet-50 text-violet-600"><Megaphone className="h-5 w-5" /></div><Badge variant="outline" className="rounded-lg border-emerald-200 bg-emerald-50 text-[10px] text-emerald-700">{campaign.status}</Badge></div><h3 className="mt-5 font-bold">{campaign.name}</h3><p className="mt-2 inline-block rounded-lg bg-slate-100 px-2 py-1 font-mono text-xs text-slate-600">{campaign.code}</p><div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-3 text-xs"><span className="text-slate-500">الأداء</span><strong>{campaign.result}</strong></div></CardContent></Card>)}</div></div>; }


function SuperAdminView() { const { user } = useAuth(); const remoteRestaurants = trpc.admin.restaurants.useQuery(undefined, { enabled: Boolean(user), retry: false }); const [restaurantsCount, setRestaurantsCount] = useState(24); const [statusFilter, setStatusFilter] = useState("الكل"); const [selectedAccount, setSelectedAccount] = useState<{ name: string; barcode: string } | null>(null); const restaurantsList = [{ name: "مطاعم مذاق", barcode: "NFOOD-00000001", branches: 4, plan: "Growth", status: "نشط" }, { name: "بيت الشواء", barcode: "NFOOD-00000002", branches: 2, plan: "Starter", status: "تجربة" }, { name: "كافيه نون", barcode: "NFOOD-00000003", branches: 7, plan: "Scale", status: "نشط" }, { name: "مطعم الساحة", barcode: "NFOOD-00000004", branches: 1, plan: "Growth", status: "معلّق" }]; const accountRows = remoteRestaurants.data?.length ? remoteRestaurants.data.map((item) => ({ name: item.name, barcode: item.barcode, branches: 0, plan: item.plan, status: item.status === "active" ? "نشط" : item.status === "trial" ? "تجربة" : "معلّق" })) : restaurantsList; const shown = accountRows.filter((item) => statusFilter === "الكل" || item.status === statusFilter); const liveCount = remoteRestaurants.data?.length ?? restaurantsCount; return <div><div className="mb-6 flex items-center justify-between"><div><h2 className="text-xl font-bold">لوحة Super Admin</h2><p className="mt-1 text-sm text-slate-500">تحكم مركزي في المطاعم والعملاء والاشتراكات والصلاحيات.</p></div><Button onClick={() => { setRestaurantsCount((value) => value + 1); toast.success("تم فتح نموذج إضافة مطعم"); }} className="gap-2 rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]"><Plus className="h-4 w-4" /> مطعم جديد</Button></div><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{([["المطاعم النشطة", "18", Store], ["إجمالي الفروع", "64", LayoutDashboard], ["الاشتراكات المدفوعة", "21", WalletCards], ["طلبات اليوم", "2,486", ShoppingBag]] as const).map(([label, value, Icon]) => { const StatIcon = Icon; return <Card key={label} className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-center justify-between"><p className="text-xs text-slate-500">{label}</p><div className="rounded-xl bg-orange-50 p-2 text-[#e76f3c]"><StatIcon className="h-4 w-4" /></div></div><p className="mt-4 text-2xl font-bold">{value}</p></CardContent></Card>; })}</div><Card className="mt-6 rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="flex-row items-center justify-between border-b border-slate-100 px-5 py-4"><div><CardTitle className="text-base">المطاعم والعملاء</CardTitle><p className="mt-1 text-xs text-slate-500">آخر المطاعم المسجلة وحالة اشتراكها.</p></div><div className="flex gap-1 rounded-xl bg-slate-100 p-1">{["الكل", "نشط", "تجربة", "معلّق"].map((item) => <button key={item} onClick={() => setStatusFilter(item)} className={`rounded-lg px-3 py-1.5 text-[11px] font-semibold ${statusFilter === item ? "bg-white text-[#e76f3c] shadow-sm" : "text-slate-500"}`}>{item}</button>)}</div></CardHeader><CardContent className="p-0"><div className="overflow-x-auto"><table className="w-full min-w-[620px] text-right text-sm"><thead className="bg-slate-50 text-[11px] text-slate-500"><tr><th className="px-5 py-3">المطعم</th><th className="px-5 py-3">الباركود</th><th className="px-5 py-3">الفروع</th><th className="px-5 py-3">الباقة</th><th className="px-5 py-3">الحالة</th><th className="px-5 py-3">إجراء</th></tr></thead><tbody>{shown.map((item) => <tr key={item.name} className="border-t border-slate-100"><td className="px-5 py-4 font-bold">{item.name}</td><td className="px-5 py-4"><div className="flex items-center gap-1"><button onClick={() => { navigator.clipboard?.writeText(item.barcode); toast.success(`تم نسخ ${item.barcode}`); }} className="flex items-center gap-2 rounded-lg bg-slate-50 px-2 py-1 text-left" title="نسخ الباركود"><Barcode value={item.barcode} width={0.8} height={24} displayValue={false} margin={0} /><span className="font-mono text-[10px] text-slate-500">{item.barcode}</span></button><button onClick={() => window.print()} className="rounded-lg px-2 py-1 text-[10px] font-semibold text-[#e76f3c] hover:bg-orange-50" title="طباعة الباركود">طباعة</button></div></td><td className="px-5 py-4 text-slate-500">{item.branches} فروع</td><td className="px-5 py-4"><Badge variant="outline" className="rounded-lg text-[11px]">{item.plan}</Badge></td><td className="px-5 py-4"><span className={`text-xs font-bold ${item.status === "نشط" ? "text-emerald-600" : item.status === "تجربة" ? "text-amber-600" : "text-slate-400"}`}>{item.status}</span></td><td className="px-5 py-4"><button onClick={() => setSelectedAccount({ name: item.name, barcode: item.barcode })} className="text-xs font-semibold text-[#e76f3c]">إدارة</button></td></tr>)}</tbody></table></div></CardContent></Card>{selectedAccount && <Card className="mt-5 rounded-2xl border-orange-200 bg-orange-50/40 shadow-sm"><CardContent className="flex flex-wrap items-center gap-5 p-5"><div><p className="text-xs text-slate-500">ملف الحساب</p><h3 className="mt-1 font-bold">{selectedAccount.name}</h3><p className="mt-1 font-mono text-xs text-slate-500">{selectedAccount.barcode}</p></div><div className="rounded-xl bg-white p-3"><Barcode value={selectedAccount.barcode} width={1.25} height={52} displayValue={false} margin={0} /></div><div className="mr-auto flex gap-2"><Button onClick={() => { navigator.clipboard?.writeText(selectedAccount.barcode); toast.success("تم نسخ باركود الحساب"); }} variant="outline" size="sm" className="rounded-lg text-xs">نسخ الباركود</Button><Button onClick={() => window.print()} size="sm" className="rounded-lg bg-[#e76f3c] text-xs hover:bg-[#d85f2e]">طباعة الباركود</Button></div></CardContent></Card>}<div className="mt-5 grid gap-4 md:grid-cols-2"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-center gap-3"><ShieldCheck className="h-5 w-5 text-[#e76f3c]" /><div><p className="font-bold">الأدوار والصلاحيات</p><p className="mt-1 text-xs text-slate-500">8 أدوار قياسية، 32 صلاحية قابلة للتخصيص.</p></div><Button onClick={() => toast.info("فتح مدير الصلاحيات")} variant="outline" size="sm" className="mr-auto rounded-lg text-xs">إدارة</Button></div></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-center gap-3"><CircleDollarSign className="h-5 w-5 text-emerald-600" /><div><p className="font-bold">الاشتراكات</p><p className="mt-1 text-xs text-slate-500">{liveCount} حسابًا في النظام{remoteRestaurants.isFetching ? " · جارٍ التحديث" : ""}.</p></div><Button onClick={() => toast.info("فتح إدارة الاشتراكات")} variant="outline" size="sm" className="mr-auto rounded-lg text-xs">عرض</Button></div></CardContent></Card></div></div>; }


function BranchesView({ restaurantId }: { restaurantId: number }) { const { user } = useAuth(); const remoteBranches = trpc.platform.branches.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false }); const [branches, setBranches] = useState([{ name: "فرع العليا", city: "الرياض", hours: "10:00 – 02:00", status: "مفتوح" }, { name: "فرع الملز", city: "الرياض", hours: "10:00 – 01:00", status: "مفتوح" }, { name: "فرع النخيل", city: "الرياض", hours: "12:00 – 02:00", status: "مغلق مؤقتاً" }]); return <div><SectionHeading title="الفروع والإعدادات" description="أدر فروع المطعم وساعات العمل وحالة التشغيل." action="إضافة فرع" /><div className="grid gap-4 md:grid-cols-3">{branches.map((branch) => <Card key={branch.name} className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-5"><div className="flex items-start justify-between"><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-orange-50 text-[#e76f3c]"><Store className="h-5 w-5" /></div><Badge variant="outline" className={`rounded-lg text-[10px] ${branch.status === "مفتوح" ? "border-emerald-200 bg-emerald-50 text-emerald-700" : "border-amber-200 bg-amber-50 text-amber-700"}`}>{branch.status}</Badge></div><h3 className="mt-5 font-bold">{branch.name}</h3><p className="mt-1 text-xs text-slate-500">{branch.city}</p><div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-3 text-xs"><span className="text-slate-500">ساعات العمل</span><strong>{branch.hours}</strong></div><div className="mt-4 flex gap-2"><Button onClick={() => setBranches((items) => items.map((item) => item.name === branch.name ? { ...item, status: item.status === "مفتوح" ? "مغلق مؤقتاً" : "مفتوح" } : item))} variant="outline" size="sm" className="flex-1 rounded-lg text-xs">تبديل الحالة</Button><Button onClick={() => toast.info(`فتح إعدادات ${branch.name}`)} variant="outline" size="sm" className="rounded-lg text-xs"><Settings2 className="h-3.5 w-3.5" /></Button></div></CardContent></Card>)}</div></div>; }

const remoteTypeLabels = { orders: "متابعة الطلبات", reservations: "الحجوزات", social: "حسابات التواصل", support: "الدعم", marketing: "التسويق", other: "أخرى" } as const;
const remoteStatusLabels = { published: "منشورة", reviewing: "قيد المراجعة", accepted: "مقبولة", in_progress: "قيد التنفيذ", submitted: "بانتظار المراجعة", completed: "مكتملة", cancelled: "ملغاة" } as const;

type RemoteTaskType = keyof typeof remoteTypeLabels;
type RemoteTaskStatus = keyof typeof remoteStatusLabels;

function RemoteWorkView({ restaurantId }: { restaurantId: number }) {
  const { user } = useAuth();
  const tasksQuery = trpc.remote.tasks.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false, refetchInterval: 5000 });
  const workersQuery = trpc.remote.workers.useQuery({ restaurantId }, { enabled: Boolean(user), retry: false });
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("0");
  const [dueAt, setDueAt] = useState("");
  const [assignedWorkerId, setAssignedWorkerId] = useState("");
  const [taskType, setTaskType] = useState<RemoteTaskType>("orders");
  const [activeTask, setActiveTask] = useState<number | null>(null);
  const [mode, setMode] = useState<"restaurant" | "worker">("restaurant");
  const [workerId, setWorkerId] = useState("1");
  const [message, setMessage] = useState("");
  const [deliveryNote, setDeliveryNote] = useState("");
  const messagesQuery = trpc.remote.messages.useQuery({ taskId: activeTask ?? 1 }, { enabled: Boolean(user && activeTask), retry: false, refetchInterval: 4000 });
  const createTask = trpc.remote.createTask.useMutation({ onSuccess: () => { tasksQuery.refetch(); setTitle(""); setDescription(""); setAmount("0"); setDueAt(""); setAssignedWorkerId(""); toast.success("تم نشر المهمة وحفظ قيمتها"); }, onError: (error) => toast.error(`تعذر نشر المهمة: ${error.message}`) });
  const updateStatus = trpc.remote.updateTaskStatus.useMutation({ onSuccess: () => tasksQuery.refetch(), onError: (error) => toast.error(`تعذر تحديث المهمة: ${error.message}`) });
  const acceptTask = trpc.remote.acceptTask.useMutation({ onSuccess: () => { tasksQuery.refetch(); toast.success("تم قبول المهمة"); }, onError: (error) => toast.error(`تعذر قبول المهمة: ${error.message}`) });
  const sendMessage = trpc.remote.sendMessage.useMutation({ onSuccess: () => { setMessage(""); messagesQuery.refetch(); }, onError: (error) => toast.error(`تعذر إرسال الرسالة: ${error.message}`) });
  const deliverTask = () => { if (!activeTask || !deliveryNote.trim()) return; sendMessage.mutate({ taskId: activeTask, body: `تسليم الموظف: ${deliveryNote}` }, { onSuccess: () => { setDeliveryNote(""); updateStatus.mutate({ taskId: activeTask, status: "submitted" }); } }); };
  const submitTask = (event: React.FormEvent) => { event.preventDefault(); if (!title.trim()) return; createTask.mutate({ restaurantId, type: taskType, title, description: description || undefined, amount: Number(amount || 0).toFixed(2), currency: "SAR", paymentMethod: "manual", assignedWorkerId: assignedWorkerId ? Number(assignedWorkerId) : undefined, dueAt: dueAt ? new Date(dueAt).toISOString() : undefined }); };
  const tasks = tasksQuery.data ?? [];
  return <div><div className="mb-6"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-bold">التوظيف عن بُعد</h2><p className="mt-1 text-sm text-slate-500">أنشئ مهامًا للطلبات والحجوزات والتواصل الاجتماعي، وحدد القيمة وطريقة التواصل والتسليم.</p></div><div className="flex items-center gap-2 rounded-xl bg-slate-100 p-1"><button onClick={() => setMode("restaurant")} className={`rounded-lg px-3 py-2 text-xs font-semibold ${mode === "restaurant" ? "bg-white text-[#e76f3c] shadow-sm" : "text-slate-500"}`}>وضع المطعم</button><button onClick={() => setMode("worker")} className={`rounded-lg px-3 py-2 text-xs font-semibold ${mode === "worker" ? "bg-white text-[#e76f3c] shadow-sm" : "text-slate-500"}`}>وضع الموظف</button></div></div>{mode === "worker" && <div className="mt-3 flex max-w-sm items-center gap-2"><Input value={workerId} onChange={(event) => setWorkerId(event.target.value)} placeholder="معرّف الموظف" className="rounded-xl" /><span className="text-xs text-slate-500">يُستخدم لقبول المهمة وتسجيل التنفيذ.</span></div>}</div><div className="grid gap-5 xl:grid-cols-[360px_1fr]"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><CardTitle className="text-base">مهمة جديدة</CardTitle></CardHeader><CardContent className="p-5"><form onSubmit={submitTask} className="space-y-4"><div><label className="mb-1.5 block text-xs font-semibold">نوع المهمة</label><select value={taskType} onChange={(event) => setTaskType(event.target.value as RemoteTaskType)} className="h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="orders">متابعة الطلبات</option><option value="reservations">الحجوزات</option><option value="social">حسابات التواصل</option><option value="support">الدعم</option><option value="marketing">التسويق</option><option value="other">أخرى</option></select></div><div><label className="mb-1.5 block text-xs font-semibold">عنوان المهمة</label><Input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="مثال: متابعة رسائل Instagram" className="rounded-xl" /></div><div><label className="mb-1.5 block text-xs font-semibold">التفاصيل وطريقة التواصل</label><textarea value={description} onChange={(event) => setDescription(event.target.value)} placeholder="اذكر المطلوب، الحساب أو القناة، وطريقة التسليم..." className="min-h-24 w-full rounded-xl border border-slate-200 p-3 text-sm outline-none focus:border-orange-300" /></div><div><label className="mb-1.5 block text-xs font-semibold">قيمة المهمة (ر.س)</label><Input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" className="rounded-xl" /></div><div className="grid grid-cols-2 gap-2"><div><label className="mb-1.5 block text-xs font-semibold">الموعد النهائي</label><Input type="datetime-local" value={dueAt} onChange={(event) => setDueAt(event.target.value)} className="rounded-xl" /></div><div><label className="mb-1.5 block text-xs font-semibold">تعيين موظف</label><select value={assignedWorkerId} onChange={(event) => setAssignedWorkerId(event.target.value)} className="h-10 w-full rounded-xl border border-slate-200 bg-white px-2 text-xs"><option value="">نشر للفريق</option>{(workersQuery.data ?? []).map((worker) => <option key={worker.id} value={worker.id}>{worker.role} #{worker.id}</option>)}</select></div></div><Button type="submit" disabled={!user || createTask.isPending} className="w-full rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{createTask.isPending ? "جارٍ النشر..." : "نشر المهمة"}</Button>{!user && <p className="text-center text-xs text-amber-600">سجّل الدخول لحفظ المهمة في قاعدة البيانات.</p>}</form></CardContent></Card><div className="space-y-4"><div className="grid gap-3 sm:grid-cols-3"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-4"><p className="text-xs text-slate-500">المهام المنشورة</p><p className="mt-2 text-2xl font-bold">{tasks.filter((task) => task.status === "published").length}</p></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-4"><p className="text-xs text-slate-500">قيد التنفيذ</p><p className="mt-2 text-2xl font-bold">{tasks.filter((task) => task.status === "in_progress").length}</p></CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardContent className="p-4"><p className="text-xs text-slate-500">العاملون المتاحون</p><p className="mt-2 text-2xl font-bold">{workersQuery.data?.filter((worker) => worker.isAvailable).length ?? 0}</p></CardContent></Card></div><div className="grid gap-4 lg:grid-cols-[1fr_320px]"><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><CardTitle className="text-base">المهام الحالية</CardTitle></CardHeader><CardContent className="space-y-3 p-5">{tasks.length === 0 ? <div className="rounded-xl bg-slate-50 p-8 text-center text-sm text-slate-500">لا توجد مهام محفوظة بعد.</div> : tasks.map((task) => <button key={task.id} onClick={() => setActiveTask(task.id)} className={`w-full rounded-xl border p-4 text-right transition ${activeTask === task.id ? "border-orange-300 bg-orange-50/50" : "border-slate-100 bg-white hover:border-orange-200"}`}><div className="flex items-start justify-between gap-3"><div><p className="font-bold">{task.title}</p><p className="mt-1 text-xs text-slate-500">{remoteTypeLabels[task.type as RemoteTaskType]} · {task.amount} {task.currency}</p></div><Badge variant="outline" className="rounded-lg text-[10px]">{remoteStatusLabels[task.status as RemoteTaskStatus]}</Badge></div><div className="mt-3 flex gap-2" onClick={(event) => event.stopPropagation()}>{mode === "worker" && task.status === "published" && <Button type="button" size="sm" onClick={() => acceptTask.mutate({ taskId: task.id, workerId: Number(workerId) })} className="h-8 rounded-lg bg-[#e76f3c] text-xs">قبول المهمة</Button>}{mode === "restaurant" && task.status === "published" && <Button type="button" size="sm" onClick={() => updateStatus.mutate({ taskId: task.id, status: "reviewing" })} className="h-8 rounded-lg bg-[#e76f3c] text-xs">بدء المراجعة</Button>}{task.status === "reviewing" && <Button type="button" size="sm" onClick={() => updateStatus.mutate({ taskId: task.id, status: "in_progress" })} className="h-8 rounded-lg bg-[#e76f3c] text-xs">بدء التنفيذ</Button>}{mode === "restaurant" && task.status !== "completed" && task.status !== "cancelled" && <Button type="button" size="sm" variant="outline" onClick={() => updateStatus.mutate({ taskId: task.id, status: "cancelled" })} className="h-8 rounded-lg text-xs text-red-600">إلغاء</Button>}{task.status === "submitted" && <Button type="button" size="sm" onClick={() => updateStatus.mutate({ taskId: task.id, status: "completed" })} className="h-8 rounded-lg bg-emerald-600 text-xs">اعتماد التسليم</Button>}</div></button>)}</CardContent></Card><Card className="rounded-2xl border-slate-200 bg-white shadow-sm"><CardHeader className="border-b border-slate-100 px-5 py-4"><CardTitle className="text-base">التواصل مع الموظف</CardTitle></CardHeader><CardContent className="p-5">{!activeTask ? <p className="py-10 text-center text-sm text-slate-500">اختر مهمة لفتح المحادثة.</p> : <><div className="mb-4 max-h-64 space-y-2 overflow-y-auto">{(messagesQuery.data ?? []).map((item) => <div key={item.id} className="rounded-xl bg-slate-50 p-3 text-sm">{item.body}<p className="mt-1 text-[10px] text-slate-400">{new Date(item.createdAt).toLocaleString("ar-SA")}</p></div>)}</div><div className="flex gap-2"><Input value={message} onChange={(event) => setMessage(event.target.value)} placeholder="اكتب رسالة..." className="rounded-xl" /><Button type="button" disabled={!message.trim() || sendMessage.isPending} onClick={() => sendMessage.mutate({ taskId: activeTask, body: message })} className="rounded-xl bg-[#e76f3c]">إرسال</Button></div>{mode === "worker" && <div className="mt-3 flex gap-2"><Input value={deliveryNote} onChange={(event) => setDeliveryNote(event.target.value)} placeholder="ملاحظة التسليم أو رابط النتيجة" className="rounded-xl" /><Button type="button" disabled={!deliveryNote.trim() || sendMessage.isPending} onClick={deliverTask} className="rounded-xl bg-emerald-600">تسليم المهمة</Button></div>}</>}</CardContent></Card></div></div></div></div>;
}

function TestLoginScreen({ email, password, setEmail, setPassword, onSubmit, pending, onOAuth }: { email: string; password: string; setEmail: (value: string) => void; setPassword: (value: string) => void; onSubmit: () => void; pending: boolean; onOAuth: () => void }) {
  return <div dir="rtl" className="flex min-h-screen items-center justify-center bg-[#f6f7f9] p-5"><Card className="w-full max-w-md rounded-3xl border-slate-200 bg-white shadow-xl"><CardContent className="p-8"><div className="mb-7 text-center"><div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-[#e76f3c] text-white"><Utensils className="h-7 w-7" /></div><h1 className="mt-4 text-2xl font-bold">تسجيل الدخول إلى NFOOD</h1><p className="mt-2 text-sm text-slate-500">استخدم حساب اختبار لتجربة مساحة المطعم والدور التشغيلي.</p></div><div className="space-y-4"><div><label className="mb-1.5 block text-xs font-semibold">البريد الإلكتروني</label><Input type="email" value={email} onChange={(event) => setEmail(event.target.value)} className="h-11 rounded-xl" /></div><div><label className="mb-1.5 block text-xs font-semibold">كلمة المرور</label><Input type="password" value={password} onChange={(event) => setPassword(event.target.value)} onKeyDown={(event) => event.key === "Enter" && onSubmit()} placeholder="أدخل كلمة المرور" className="h-11 rounded-xl" /></div><Button type="button" onClick={onSubmit} disabled={pending || !email || !password} className="h-11 w-full rounded-xl bg-[#e76f3c] hover:bg-[#d85f2e]">{pending ? "جارٍ تسجيل الدخول..." : "دخول حساب الاختبار"}</Button><Button type="button" variant="outline" onClick={onOAuth} className="h-11 w-full rounded-xl">الدخول عبر OAuth</Button></div><p className="mt-5 text-center text-[11px] leading-5 text-slate-400">حسابات الاختبار مخصصة للتجربة فقط. لا تستخدمها في بيئة الإنتاج.</p></CardContent></Card></div>;
}
